import glob, json, re, sys, time, difflib, unicodedata, urllib.parse, urllib.request

R = "/Users/kristinarash/DEV/SportScienceResearchRepo"
OUT = f"{R}/docs/doi-lookup/2026-10-12-degraded-doi-candidates.json"

def norm(s):
    s = unicodedata.normalize("NFKD", s).encode("ascii", "ignore").decode().lower()
    s = re.sub(r"\(.*?\)", " ", s)
    s = re.sub(r"[^a-z0-9 ]+", " ", s)
    return re.sub(r"\s+", " ", s).strip()

# DEGRADED records whose reason is "DOI not printed" (the 88 in needs-eric section 2)
targets = []
for f in sorted(glob.glob(f"{R}/docs/pilot-screening/*.json")):
    for r in json.load(open(f, encoding="utf8"))["records"]:
        if r.get("decision") == "DEGRADED" and re.search(r"\bDOI\b", r.get("degradedReason", ""), re.I):
            targets.append({"sourceFile": r["sourceFile"], "batch": f.split("/")[-1].replace(".json", ""),
                            "reason": r["degradedReason"]})
print("targets", len(targets), file=sys.stderr)

def crossref(title):
    q = urllib.parse.urlencode({"query.bibliographic": title, "rows": 3})
    req = urllib.request.Request(f"https://api.crossref.org/works?{q}", headers={"User-Agent": "research-repo-doi-lookup/1.0"})
    with urllib.request.urlopen(req, timeout=30) as resp:
        return json.load(resp)["message"]["items"]

results = []
for t in targets:
    stem = re.sub(r"\.pdf$", "", t["sourceFile"], flags=re.I)
    stem = re.sub(r"\s+copy$", "", stem, flags=re.I).strip()
    entry = {**t, "query": stem, "doi": None, "crossrefTitle": None, "crossrefYear": None,
             "titleSimilarity": 0.0, "status": "NO_MATCH"}
    try:
        items = crossref(stem)
    except Exception as e:
        entry["status"] = f"ERROR: {e}"
        results.append(entry)
        continue
    best, best_score = None, 0.0
    for it in items:
        cand_title = (it.get("title") or [""])[0]
        score = difflib.SequenceMatcher(None, norm(stem), norm(cand_title)).ratio()
        if score > best_score:
            best, best_score = it, score
    if best is not None:
        parts = (best.get("published-print") or best.get("published-online") or best.get("issued") or {}).get("date-parts", [[None]])
        entry.update({"doi": best.get("DOI"), "crossrefTitle": (best.get("title") or [""])[0],
                      "crossrefYear": parts[0][0], "titleSimilarity": round(best_score, 3)})
        if best_score >= 0.90 and best.get("DOI"):
            entry["status"] = "STRONG_MATCH"
        elif best_score >= 0.70 and best.get("DOI"):
            entry["status"] = "CHECK_BY_HAND"
    results.append(entry)
    time.sleep(0.15)

counts = {}
for e in results:
    counts[e["status"]] = counts.get(e["status"], 0) + 1
out = {"generated": "2026-10-12", "source": "Crossref REST API (query.bibliographic, top 3 per file)",
       "rule": "STRONG_MATCH = title similarity >= 0.90 with DOI. CHECK_BY_HAND = 0.70 to 0.90. Nothing here is written to papers.json.",
       "counts": counts, "records": results}
json.dump(out, open(OUT, "w", encoding="utf8"), indent=2, ensure_ascii=False)
print(json.dumps(counts, indent=1))

